/* Page renderers. Each function receives the build context and calls write(). */
import { LOAN_TYPES, STATES } from './lenders.mjs';
import { FORECLOSURE } from './states.mjs';

const stateOptions = (sel = '') => Object.entries(STATES).map(([c, n]) => `<option value="${c}"${c === sel ? ' selected' : ''}>${n}</option>`).join('');
const typeOptions = () => Object.entries(LOAN_TYPES).map(([k, v]) => `<option value="${k}">${v}</option>`).join('');
const consent = `<label class="consent"><input type="checkbox" name="consent" value="yes" required> I agree to the <a href="/terms/">Terms</a> and <a href="/privacy/">Privacy Policy</a> and consent to be contacted by Hard.Money and matched lenders by phone, email or text about my request (message/data rates may apply). Consent is not a condition of any service. I can opt out at any time.</label>`;
const honey = `<input class="hp" type="text" name="_honey" tabindex="-1" autocomplete="off" aria-hidden="true">`;

