/* ---------------- APPLY (lead funnel) ---------------- */
function apply(c) {
  const { layout, write, pageHead } = c;
  const body = `${pageHead('Request funding from vetted private lenders', 'One request, multiple lenders, no obligation and no credit pull. The more complete your deal, the firmer and faster the terms. Typical first response: within 24 hours.', 'Free funding request')}
<section class="section" style="padding-top:0"><div class="wrap"><div class="layout">
<div class="card" data-multistep>
  <div class="steps"><i></i><i></i><i></i><i></i><i></i></div>
  <form data-hm="Funding Request" data-next="/thank-you/" novalidate>
    ${honey}
    <div class="step" data-auto>
      <h2 style="font-size:1.3rem">1. What are you financing?</h2>
      <div class="chips">
        ${['Fix & Flip', 'Bridge / Purchase', 'Rental / DSCR Refinance', 'New Construction', 'Commercial Property', 'Cash-Out Refinance', 'Land / Lot', 'Not sure yet'].map(t => `<label class="chip"><input type="radio" name="loan_type" value="${t}" required>${t}</label>`).join('')}
      </div>
      <div class="step-nav"><span></span><button type="button" class="btn" data-next-step>Continue →</button></div>
    </div>
    <div class="step">
      <h2 style="font-size:1.3rem">2. The property</h2>
      <div class="row"><div><label>Property type</label><select name="property_type" required><option value="">Select…</option><option>Single-family</option><option>2–4 units</option><option>5+ unit multifamily</option><option>Mixed-use</option><option>Commercial (retail/office/industrial)</option><option>Land</option><option>Portfolio (multiple properties)</option></select></div><div><label>State</label><select name="state" required><option value="">Select…</option>${stateOptions()}</select></div></div>
      <div class="row"><div><label>City or ZIP</label><input name="city" required></div><div><label>Property address <span class="help">(optional)</span></label><input name="address" autocomplete="street-address"></div></div>
      <label>Will you or a family member live in the property?</label>
      <div class="chips"><label class="chip"><input type="radio" name="owner_occupied" value="No" required>No — investment / business purpose</label><label class="chip"><input type="radio" name="owner_occupied" value="Yes" required>Yes</label></div>
      <p class="help">Hard money is for non-owner-occupied, business-purpose loans. Owner-occupied requests are routed to licensed mortgage partners where available.</p>
      <div class="step-nav"><button type="button" class="btn outline" data-prev-step>← Back</button><button type="button" class="btn" data-next-step>Continue →</button></div>
    </div>
    <div class="step">
      <h2 style="font-size:1.3rem">3. The numbers</h2>
      <div class="row"><div><label>Purchase price / current value ($)</label><input name="purchase_price" type="number" min="0" step="1000" inputmode="numeric" required placeholder="250000"></div><div><label>Rehab / construction budget ($)</label><input name="rehab_budget" type="number" min="0" step="1000" inputmode="numeric" placeholder="60000"></div></div>
      <div class="row"><div><label>After-repair value (ARV) ($)</label><input name="arv" type="number" min="0" step="1000" inputmode="numeric" placeholder="400000"></div><div><label>Loan amount requested ($)</label><input name="loan_amount" type="number" min="0" step="1000" inputmode="numeric" required placeholder="280000"></div></div>
      <div class="estimate" style="display:none"></div>
      <div class="row"><div><label>Timeline to close</label><select name="timeline" required><option value="">Select…</option><option>Under 2 weeks</option><option>2–4 weeks</option><option>1–2 months</option><option>Exploring options</option></select></div><div><label>Exit strategy</label><select name="exit" required><option value="">Select…</option><option>Sell after renovation</option><option>Refinance into long-term loan (hold)</option><option>Sell as-is / wholesale</option><option>Undecided</option></select></div></div>
      <div class="step-nav"><button type="button" class="btn outline" data-prev-step>← Back</button><button type="button" class="btn" data-next-step>Continue →</button></div>
    </div>
    <div class="step">
      <h2 style="font-size:1.3rem">4. About you</h2>
      <label>Completed investment projects in the last 3 years</label>
      <div class="chips">${['0', '1–2', '3–5', '6–10', '10+'].map(t => `<label class="chip"><input type="radio" name="experience" value="${t}" required>${t}</label>`).join('')}</div>
      <label>Estimated credit score</label>
      <div class="chips">${['Below 600', '600–659', '660–699', '700–739', '740+', 'Not sure'].map(t => `<label class="chip"><input type="radio" name="credit" value="${t}" required>${t}</label>`).join('')}</div>
      <div class="row"><div><label>Liquid funds available for this deal</label><select name="liquidity" required><option value="">Select…</option><option>Under $25K</option><option>$25K – $50K</option><option>$50K – $100K</option><option>$100K – $250K</option><option>Over $250K</option></select></div><div><label>Borrowing entity</label><select name="entity" required><option value="">Select…</option><option>LLC / Corporation (existing)</option><option>Will form an LLC</option><option>Individual</option><option>I am a broker submitting for a client</option></select></div></div>
      <div class="step-nav"><button type="button" class="btn outline" data-prev-step>← Back</button><button type="button" class="btn" data-next-step>Continue →</button></div>
    </div>
    <div class="step">
      <h2 style="font-size:1.3rem">5. Where should lenders send terms?</h2>
      <div class="row"><div><label>Full name</label><input name="name" required autocomplete="name"></div><div><label>Company <span class="help">(optional)</span></label><input name="company" autocomplete="organization"></div></div>
      <div class="row"><div><label>Email</label><input name="email" type="email" required autocomplete="email"></div><div><label>Mobile phone</label><input name="phone" type="tel" required autocomplete="tel"></div></div>
      <label>Anything else lenders should know? <span class="help">(optional)</span></label><textarea name="notes" rows="3" placeholder="Scope of work, comps, partner details, deadlines…"></textarea>
      ${consent}
      <div class="step-nav"><button type="button" class="btn outline" data-prev-step>← Back</button><button type="submit" class="btn lg">Submit funding request →</button></div>
      <div class="form-msg"></div>
      <p class="help" style="margin-top:12px">Submitting does not pull your credit or obligate you to accept any offer. Hard.Money is not a lender; your information is shared only with lenders matched to your request. <a href="/privacy/">Privacy Policy</a>.</p>
    </div>
  </form>
</div>
<aside class="side">
  <div class="card"><h4>What happens next</h4><ol style="padding-left:1.2em;margin:0"><li>We review your request for completeness (same day).</li><li>Matched lenders receive your deal summary.</li><li>Lenders contact you directly with indicative terms — typically within 24 hours.</li><li>You compare, choose, and move to underwriting.</li></ol></div>
  <div class="card"><h4>What you'll need later</h4><ul><li>Purchase contract or payoff statement</li><li>Scope of work and budget</li><li>Two months of bank statements</li><li>Entity documents (LLC)</li><li>Photos and comps</li></ul><p class="help">Nothing is required to submit today.</p></div>
  <div class="card"><h4>Not ready?</h4><p style="font-size:.95rem">Run your deal through the <a href="/calculators/fix-and-flip/">fix &amp; flip calculator</a> or read <a href="/learn/hard-money-loan-requirements/">what lenders check</a>.</p></div>
</aside>
</div></div></section>`;
  write('/apply/', layout({ title: 'Get Funded — Request Hard Money Loan Terms From Vetted Lenders', desc: 'Submit one free funding request and receive indicative terms from multiple vetted hard money and private lenders, typically within 24 hours. No credit pull, no obligation.', url: '/apply/', body, ads: false, crumbs: [[null, 'Get Funded']] }));

  write('/thank-you/', layout({ title: 'Request Received', desc: 'Your funding request has been received.', url: '/thank-you/', ads: false, noindex: true, body: `<section class="section"><div class="wrap narrow center"><span class="badge green">Received</span><h1 style="margin-top:14px">Your request is in.</h1><p class="lead muted">Here is what happens next: we review it for completeness today, matched lenders receive your deal summary, and you should hear from them directly — usually within one business day. Check your email (and spam folder) for a confirmation.</p><div class="grid-3 mt2" style="text-align:left"><a class="feature" href="/learn/hard-money-loan-requirements/"><h3>Prepare your file</h3><p class="muted">What lenders will ask for next.</p></a><a class="feature" href="/calculators/hard-money-loan/"><h3>Compare offers</h3><p class="muted">Model total cost of each term sheet.</p></a><a class="feature" href="/learn/hard-money-exit-strategies/"><h3>Plan the exit</h3><p class="muted">Sale, refinance or extension.</p></a></div><p class="mt2"><a class="btn dark" href="/">Back to home</a></p></div></section>` }));
}

/* ---------------- LOANS ---------------- */
function loanPages(c) {
  const { layout, write, loans, esc, pageHead, ad, ctaInline, faqBlock, faqLd, sidebar } = c;
  write('/loans/', layout({ title: 'Hard Money Loan Types: Fix & Flip, Bridge, DSCR, Construction, Commercial', desc: 'Compare every type of hard money and private real estate loan — fix and flip, bridge, DSCR rental, ground-up construction, commercial, land and bad-credit options — with 2026 terms.', url: '/loans/', crumbs: [[null, 'Loan Types']], body: `${pageHead('Loan types', 'Every private-lending product explained with indicative 2026 terms, requirements and FAQs. Click through for the full guide, or <a href="/apply/">request terms</a> for your deal.', 'Programs')}
<section class="section" style="padding-top:0"><div class="wrap">
<div class="tbl-wrap mb2"><table class="tbl"><tr><th>Program</th><th>Rates</th><th>Points</th><th>Leverage</th><th>Term</th><th>Best for</th></tr>${loans.map(l => `<tr><td><a href="/loans/${l.slug}/"><strong>${esc(l.title)}</strong></a></td><td><b>${l.terms.Rates}</b></td><td>${l.terms.Points}</td><td>${l.terms['Max LTC'] || l.terms['Max LTV'] || '—'}${l.terms['Max ARV'] ? ' / ' + l.terms['Max ARV'] + ' ARV' : ''}</td><td>${l.terms.Term}</td><td>${l.blurb.split(' ').slice(0, 10).join(' ')}…</td></tr>`).join('')}</table></div>
<div class="grid-3">${loans.map(l => `<div class="feature stretched"><div class="ico">${l.ico}</div><h3><a class="cover" href="/loans/${l.slug}/">${esc(l.title)}</a></h3><p class="muted">${l.blurb}</p></div>`).join('')}</div>
${ad()}
${ctaInline()}
</div></section>` }));

  for (const l of loans) {
    const body = `${pageHead(l.title, l.blurb, 'Loan program')}
<section class="section" style="padding-top:0"><div class="wrap"><div class="layout"><div class="prose">
<div class="card" style="margin-bottom:26px"><h3 style="margin:0 0 10px">Indicative 2026 terms</h3><div class="terms" style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;font-family:var(--mono);font-size:.9rem">${Object.entries(l.terms).map(([k, v]) => `<div><span class="muted" style="font-family:var(--font);font-size:.78rem;display:block">${k}</span><b>${v}</b></div>`).join('')}</div><p class="help" style="margin:12px 0 0">Compiled from published lender rate sheets and broker quotes. Not an offer; terms are set by each lender.</p></div>
<p class="lead" style="font-size:1.12rem">${l.intro}</p>
${l.sections.map(([h, html], i) => `<h2 id="${c.slug(h)}">${h}</h2>${html}${i === 0 ? ad() : ''}${i === 1 ? ctaInline(`Request ${l.short.toLowerCase()} terms`, 'Vetted lenders that specialize in this program respond within 24 hours.') : ''}`).join('')}
<h2 id="faq">Frequently asked questions</h2>${faqBlock(l.faqs)}
<h2 id="related">Related</h2><div class="pill-list">${loans.filter(x => x.slug !== l.slug).map(x => `<a href="/loans/${x.slug}/">${esc(x.short)}</a>`).join('')}<a href="/lenders/?type=${l.type}">Lenders offering ${esc(l.short)}</a><a href="/rates/">Current rates</a></div>
</div>${sidebar()}</div></div></section>`;
    write(`/loans/${l.slug}/`, layout({ title: `${l.title}: Rates, Terms & Requirements (2026)`, desc: l.desc, url: `/loans/${l.slug}/`, body, crumbs: [['/loans/', 'Loan Types'], [null, l.title]], schema: [faqLd(l.faqs), { '@context': 'https://schema.org', '@type': 'FinancialProduct', name: l.title, description: l.blurb, provider: { '@type': 'Organization', name: 'Hard.Money (referral service)' } }] }));
  }
  // rates page
  write('/rates/', layout({ title: 'Hard Money Loan Rates & Terms — October 2026 Market Matrix', desc: 'Current hard money loan rates, points, leverage and terms by loan type and borrower tier, updated October 2026, with what moves pricing and how to compare offers.', url: '/rates/', crumbs: [['/loans/', 'Loan Types'], [null, 'Rates & Terms']], body: `${pageHead('Hard money rates &amp; terms', 'Indicative market ranges as of <strong>October 30, 2026</strong>, compiled from the published rate sheets of national lenders and broker quotes. Updated quarterly. These are not offers; your pricing depends on experience, credit, leverage, property and state.', 'Market data')}
<section class="section" style="padding-top:0"><div class="wrap"><div class="layout"><div class="prose">
<h2>By loan type</h2><div class="tbl-wrap"><table class="tbl"><tr><th>Program</th><th>Rate</th><th>Points</th><th>Max leverage</th><th>Term</th><th>Min FICO</th></tr>${loans.map(l => `<tr><td><a href="/loans/${l.slug}/">${esc(l.title)}</a></td><td><b>${l.terms.Rates}</b></td><td>${l.terms.Points}</td><td>${l.terms['Max LTC'] || l.terms['Max LTV'] || '—'}${l.terms['Max ARV'] ? ' / ' + l.terms['Max ARV'] + ' ARV' : ''}</td><td>${l.terms.Term}</td><td>${l.terms['Min FICO'] || l.terms['Min DSCR'] || '—'}</td></tr>`).join('')}</table></div>
<h2>Fix &amp; flip pricing by experience tier</h2><div class="tbl-wrap"><table class="tbl"><tr><th>Tier</th><th>Flips (36 mo)</th><th>Max LTC</th><th>Max LTARV</th><th>Rate</th><th>Points</th></tr><tr><td>New</td><td>0</td><td>80%</td><td>70%</td><td><b>10.5% – 11.5%</b></td><td>2 – 2.5</td></tr><tr><td>Emerging</td><td>1–2</td><td>85%</td><td>70–72.5%</td><td><b>10.0% – 10.75%</b></td><td>1.5 – 2</td></tr><tr><td>Experienced</td><td>3–5</td><td>90%</td><td>75%</td><td><b>9.25% – 10.0%</b></td><td>1 – 1.5</td></tr><tr><td>Professional</td><td>6+</td><td>92.5–95%</td><td>75%</td><td><b>8.25% – 9.5%</b></td><td>1 – 1.5</td></tr></table></div>
${ad()}
<h2>Pricing adjustments to expect</h2><div class="tbl-wrap"><table class="tbl"><tr><th>Factor</th><th>Typical adjustment</th></tr><tr><td>Credit 660–699 vs 740+</td><td>+50 to +100 bps</td></tr><tr><td>Each 5% leverage reduction</td><td>−20 to −30 bps</td></tr><tr><td>2–4 units vs SFR</td><td>+12 to +25 bps</td></tr><tr><td>Heavy rehab (>50% of price)</td><td>+25 to +50 bps, lower LTARV</td></tr><tr><td>Judicial-foreclosure state (NY, NJ, FL, IL, OH)</td><td>+50 to +150 bps</td></tr><tr><td>Loan under $150,000</td><td>Rate floor or minimum points</td></tr><tr><td>Rural / tertiary market</td><td>+50 bps, −5% leverage, or declined</td></tr></table></div>
<h2>Standard fees</h2><ul><li>Document / underwriting: $995 – $2,000</li><li>Valuation (BPO / appraisal): $300 – $900</li><li>Draw inspection: $150 – $300</li><li>Extension: 0.5 – 1 point per 3–6 months</li><li>Legal / closing: $750 – $2,500 (varies by state)</li></ul>
<p>Read <a href="/learn/hard-money-loan-rates/">how rates and points are set</a> and model any term sheet in the <a href="/calculators/hard-money-loan/">cost calculator</a>.</p>
${ctaInline('Get real quotes for your deal', 'Market ranges are a starting point. Lenders price your file in 24 hours.')}
</div>${sidebar()}</div></div></section>` }));
}

