  const topics = [...new Set(videos.map(v => v.topic))];
  const card = (v) => `<div class="video-card"><div class="video" data-yt="${v.id}" data-title="${esc(v.title)}" role="button" tabindex="0" aria-label="Play: ${esc(v.title)}"><img src="https://i.ytimg.com/vi/${v.id}/hqdefault.jpg" alt="${esc(v.title)}" loading="lazy" width="480" height="360"><div class="play"><span>▶</span></div></div><h3>${esc(v.title)}</h3><p>${esc(v.channel)} · ${esc(v.blurb)}</p></div>`;
